, sum(cast(DefensiveMetrics.competitive_play as int)) as TrackedCompetitivePlays
, sum(cast(DefensiveMetrics.out_made as int)) as OutsMade
, sum(case when DefensiveMetrics.competitive_throw = 1 and DefensiveMetrics.pos_id in (3,4,5,6) and DefensiveMetrics.arm_strength >= 60 and DefensiveMetrics.arm_strength <= 94 then 1 else 0 end) as ArmStrengthThrowsINF
